cases.input:
.instance { anchor-scope: --input; }
.input { anchor-name: --input; }
.popup { position: absolute; position-anchor: --input; top: calc(anchor(bottom) + 8px); left: anchor(left); width: anchor-size(width); max-height: 160px; overflow-y: auto; }
@media (prefers-color-scheme: dark) { .popup { background: #171717; } }

